public void saveSourceTable(TableDesc srcTable) throws IOException {
  if (srcTable.getUuid() == null || srcTable.getIdentity() == null) {
    throw new IllegalArgumentException();
  }
  try {
    srcTable.init();
    String path = srcTable.getResourcePath();
    getStore().putResource(path, srcTable, TABLE_SERIALIZER);
    srcTableMap.put(srcTable.getIdentity(), srcTable);
  } catch (ClassCastException | UnsupportedOperationException | IllegalArgumentException | NumberFormatException | IllegalFormatException | IndexOutOfBoundsException e) {
    // Handle the exception, e.g., log the error or take appropriate action
    e.printStackTrace();
  }
}
